# Tensor names carrying per-sequence length information, per framework.
_SGLANG_SEQ_LENS_NAME: str = "seq_lens"
_MEGATRON_CU_SEQLENS_NAME: str = "cu_seqlens_q"


def load_thd_seq_lens_only(
    dump_path: Path,
    df: pl.DataFrame,
) -> Optional[dict[int, list[int]]]:
    """Load per-step sequence lengths without running the full alignment pipeline.

    Returns ``{step: [len1, len2, ...]}`` for every step present in the dump, or
    ``None`` if no recognized framework plugin is detected, if the detected plugin
    reports no CP-sharded names, or if neither a ``seq_lens`` (SGLang) nor a
    ``cu_seqlens_q`` (Megatron) tensor is present.
    """
    plugin = _detect_plugin(df, dump_path=dump_path)
    if plugin is None:
        return None

    # No CP sharding → nothing to derive THD sequence lengths for.
    if not plugin.cp_sharded_names:
        return None

    names: set[str] = set(df["name"].unique().to_list())
    if _SGLANG_SEQ_LENS_NAME in names:
        source_name: str = _SGLANG_SEQ_LENS_NAME
        derive_from_cumsum: bool = False
    elif _MEGATRON_CU_SEQLENS_NAME in names:
        source_name = _MEGATRON_CU_SEQLENS_NAME
        derive_from_cumsum = True
    else:
        return None

    steps: list[int] = sorted(df["step"].unique().to_list())

    result: dict[int, list[int]] = {}
    for step in steps:
        tensor: Optional[torch.Tensor] = _load_tensor(
            name=source_name, step=step, df=df, dump_path=dump_path
        )
        if tensor is None:
            continue

        if derive_from_cumsum:
            lengths: list[int] = (tensor[1:] - tensor[:-1]).tolist()
        else:
            lengths = tensor.tolist()

        result[int(step)] = [int(length) for length in lengths]

    return result


def _load_tensor(
    *, name: str, step: int, df: pl.DataFrame, dump_path: Path
) -> Optional[torch.Tensor]:
    rows = filter_rows(df, conditions={"name": name, "step": step})
    if not rows:
        return None

    loaded: list[ValueWithMeta] = [
        ValueWithMeta.load(dump_path / r["filename"]) for r in rows
    ]
    loaded = filter_to_non_empty_dp_rank(loaded)

    for item in loaded:
        if isinstance(item.value, torch.Tensor):
            return item.value

    return None
